import click
from click.testing import CliRunner

CLEAN = {"POINT": None, "TAGS": None, "PAIR": None, "APP_POINT": None}


def env(**values):
    return {**CLEAN, **values}


@click.command()
@click.option("--point", nargs=2, type=int, multiple=True, envvar="POINT")
@click.option("--tag", multiple=True, envvar="TAGS")
@click.option("--pair", nargs=2, envvar="PAIR")
def cli(point, tag, pair):
    click.echo(f"point={point} tag={tag} pair={pair}")


@click.command(context_settings={"auto_envvar_prefix": "APP"})
@click.option("--point", nargs=2, type=int, multiple=True)
def auto(point):
    click.echo(f"point={point}")


runner = CliRunner()


def bad(cmd, environ, name):
    result = runner.invoke(cmd, [], env=environ)
    assert result.exit_code == 2, (environ, result.output)
    assert "Invalid value" in result.output, (environ, result.output)
    result = runner.invoke(cmd, [], env=environ, standalone_mode=False)
    exc = result.exception
    assert isinstance(exc, click.BadParameter), (environ, repr(exc), result.return_value)
    assert exc.param is not None and exc.param.name == name, (environ, exc.param)


def ok(cmd, args, environ, expect):
    result = runner.invoke(cmd, args, env=environ)
    assert result.exit_code == 0, (args, environ, result.output)
    assert result.output == expect, (args, environ, result.output)


bad(cli, env(POINT="1 2 3"), "point")
bad(cli, env(POINT="7"), "point")
bad(cli, env(POINT="1 2 3 4 5"), "point")
bad(auto, env(APP_POINT="1 2 3"), "point")

ok(cli, [], env(POINT="1 2 3 4"), "point=((1, 2), (3, 4)) tag=() pair=None\n")
ok(cli, [], env(POINT="1 2"), "point=((1, 2),) tag=() pair=None\n")
ok(cli, [], env(), "point=() tag=() pair=None\n")
ok(cli, [], env(POINT=""), "point=() tag=() pair=None\n")
ok(cli, ["--point", "5", "6"], env(POINT="1 2 3"), "point=((5, 6),) tag=() pair=None\n")
ok(cli, [], env(TAGS="a b c"), "point=() tag=('a', 'b', 'c') pair=None\n")
ok(cli, [], env(PAIR="x y"), "point=() tag=() pair=('x', 'y')\n")
bad(cli, env(PAIR="x y z"), "pair")
ok(auto, [], env(APP_POINT="1 2 3 4"), "point=((1, 2), (3, 4))\n")

