def test_command_collection_sources(runner):
    @click.group()
    def first():
        pass

    @first.command("shared")
    def first_shared():
        click.echo("shared from first")

    @first.command("alpha")
    def alpha():
        click.echo("alpha")

    @click.group()
    def second():
        pass

    @second.command("shared")
    def second_shared():
        click.echo("shared from second")

    @second.command("beta")
    def beta():
        click.echo("beta")

    cli = click.CommandCollection(sources=[first, second])

    result = runner.invoke(cli, ["shared"])
    assert result.exit_code == 0
    assert result.output == "shared from first\n"

    result = runner.invoke(cli, ["beta"])
    assert result.exit_code == 0
    assert result.output == "beta\n"

    ctx = click.Context(cli)
    assert cli.list_commands(ctx) == ["alpha", "beta", "shared"]

